const policy=JSON.parse(fs.readFileSync("config/orchestrator-policy.json","utf8")),results={};let seq=0;
const hex=(n,c)=>String(c).repeat(n),sha40=()=>(++seq).toString(16).padStart(40,"a"),sha64=()=>(++seq).toString(16).padStart(64,"b");
const T0=new Date("2026-09-29T00:00:00.000Z"),at=m=>new Date(T0.getTime()+m*60_000);
function tmp(){return fs.mkdtempSync(path.join(os.tmpdir(),"uasco-orch-selftest-"))}
function reviewPkg(id,extra={}){return {id,kind:"REVIEW",status:"REVIEW_PENDING",baseCommit:sha40(),reviewCommit:sha40(),cycle:1,bundle:{file:`${id}.json`,promptFile:`${id}.txt`,digest:sha64()},merge:{mode:"FF_DEFAULT_BRANCH",after:[]},dependsOn:[],...extra}}
function implPkg(id,extra={}){return {id,kind:"IMPLEMENT",status:"IMPLEMENT_PENDING",cycle:1,merge:{mode:"FF_DEFAULT_BRANCH",after:[]},dependsOn:[],specFile:"spec.json",...extra}}
function control(pkgs,extra={}){const c={schemaVersion:CONTROL_VERSION,order:pkgs.map(p=>p.id),packages:Object.fromEntries(pkgs.map(p=>[p.id,p])),releases:{},providers:{codex:{status:"AVAILABLE",retryAfter:null},claude:{status:"AVAILABLE",retryAfter:null}},...extra};validateControl(c);return c}
function store(c){const d=tmp(),stateFile=path.join(d,"ORCHESTRATOR_STATE.json"),logFile=path.join(d,"transitions.jsonl");let doc={"//TR":"selftest",legacy:true};const persist=(next,event)=>{const r=commitTransition({stateFile,logFile,doc,next,event});doc=r.doc;return r.control};return {persist,stateFile,logFile,start:persist(c,{type:"SEED"}),get doc(){return doc}}}
async function ticks(s,c,executors,times){let ctl=c;const log=[];for(const t of times){const r=await runTick({control:ctl,executors,persist:s.persist,policy,workerId:"w1",now:()=>t});ctl=r.control;log.push(...r.done)}return {control:ctl,log}}
function fakeExec(o={}){const calls={review:0,implement:0,remediate:0,merge:0,package:0,sign:0,phase0:0,audit_freeze:0,audit:0};return {calls,exec:{
  audit_freeze:async()=>{calls.audit_freeze++;return {type:"FROZEN",bundle:{file:"audit.json",promptFile:"audit.txt",digest:sha64()},baseCommit:policy.releaseAudit.emptyBaseCommit,fileCount:1}},
  audit:async(a,c)=>{calls.audit++;return o.audit?o.audit(a,c,calls):{type:"CLEAN",runDir:`audit-${a.provider}`,evidence:`audit-ev-${a.provider}`}},
  review:async(a,c)=>{calls.review++;return o.review?o.review(a,c,calls):{type:"CLEAN",runDir:"run",evidence:"ev"}},
  implement:async(a,c)=>{calls.implement++;return o.implement?o.implement(a,c,calls):{type:"COMMITTED",commit:sha40(),baseCommit:sha40(),cycle:1,bundle:{file:"b.json",promptFile:"b.txt",digest:sha64()},executionBackend:"LOCAL_CLAUDE"}},
  remediate:async(a,c)=>{calls.remediate++;return o.remediate?o.remediate(a,c,calls):{type:"COMMITTED",commit:sha40(),cycle:c.packages[a.packageId].cycle+1,bundle:{file:"r.json",promptFile:"r.txt",digest:sha64()}}},
  merge:async()=>{calls.merge++;return {type:"MERGED",master:sha40()}},close:async()=>({type:"CLOSED"}),
  package:async()=>{calls.package++;return {type:"PACKAGED",record:{zip:{file:"z.zip",sha256:sha64()},signDir:"s"}}},
  sign:async(a,c)=>{calls.sign++;return o.sign?o.sign(a,c,calls):{type:"SIGNED",signatures:[]}},
  phase0:async()=>{calls.phase0++;return o.phase0?o.phase0():{type:"PHASE0_DONE",final:"CLEAN_LOCAL_ONLY",installRoot:"C:/UASCO"}}}}}
async function scenario(name,fn){try{await fn();results[name]="PASS"}catch(e){results[name]=`FAIL: ${e.message}`}}
const assert=(cond,msg)=>{if(!cond)throw new Error(msg)};
await scenario("e2e-implement-review-clean-integrate-next-package-release",async()=>{
  const c=control([implPkg("A"),implPkg("B",{dependsOn:[{package:"A"}],release:true})]),s=store(c),{calls,exec}=fakeExec();
  const r=await ticks(s,s.start,exec,[at(0),at(15),at(30),at(45),at(60),at(75)]);const f=r.control;
  assert(f.packages.A.status==="CLOSED"&&f.packages.B.status==="CLOSED","packages not closed");assert(calls.implement===2&&calls.review===2&&calls.merge===2,`calls ${JSON.stringify(calls)}`);
  const seqA=r.log.findIndex(x=>x.target==="A"&&x.action==="MERGE"),seqB=r.log.findIndex(x=>x.target==="B"&&x.action==="IMPLEMENT");assert(seqA>=0&&seqB>seqA,"B implemented before A merged");
  const rel=Object.values(f.releases)[0];assert(rel&&rel.status==="PHASE0_DONE"&&rel.phase0Final==="CLEAN_LOCAL_ONLY","release pipeline not completed honestly");
  const audits=r.log.filter(x=>x.action==="AUDIT"),pk=r.log.findIndex(x=>x.action==="PACKAGE");assert(calls.audit_freeze===1&&audits.length===2&&rel.audit?.result==="CLEAN"&&rel.audit.dualClean===true&&r.log.findIndex(x=>x.action==="AUDIT_FREEZE")<pk&&r.log.map((x,i)=>x.action==="AUDIT"?i:-1).filter(i=>i>=0).every(i=>i<pk),`release not dual-audited before packaging: ${JSON.stringify(r.log.map(x=>x.action))}`);assert(verifyTransitionLog(s.logFile,f).ok,"log chain");});
